const nowIso = () => new Date().toISOString();

const newId = (prefix) => {
  const rand = Array.from({ length: 12 }, () =>
    'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(Math.random() * 36)]
  ).join('');
  return prefix + '_' + rand;
};

// Acuity ranking. Used only to clamp a decision upward; nothing may move down.
const TIER_ACUITY = {
  SELF_CARE: 0,
  PRIMARY_CARE: 1,
  FERTILITY_SERVICES: 2,
  ANDROLOGY_UROLOGY: 3,
  URGENT: 4,
};

const escalateOnly = (current, proposed) =>
  (TIER_ACUITY[proposed] ?? -1) > (TIER_ACUITY[current] ?? -1) ? proposed : current;

const auditDoc = (ctx) => ({
  at: nowIso(),
  actor: ctx.actor,
  action: ctx.action,
  pseudonymId: ctx.pseudonymId ?? null,
  subjectRef: ctx.subjectRef ?? null,
  consentId: ctx.consentId ?? null,
  workflowRunId: ctx.runId ?? null,
  outcome: ctx.outcome ?? 'ok',
  meta: ctx.meta ?? {},
});

// Discreet by default: nothing clinical ever appears in a subject line or preview.
const DISCREET_SUBJECT = {
  en: 'Your Vigor update',
  ar: 'تحديث من فيجور',
};
// ---------------------------------------------------------------------------


const ALL_SCOPES = [
  'ASSESSMENT',
  'STORE_RESULTS',
  'SHARE_WITH_CLINICIAN',
  'SHARE_WITH_FERTILITY_SERVICE',
  'AT_HOME_TESTING',
  'CONTACT_REMINDERS',
  'RESEARCH_AGGREGATE',
];

// Scopes whose withdrawal must kill outstanding share tokens.
const SHARING_SCOPES = new Set(['SHARE_WITH_CLINICIAN', 'SHARE_WITH_FERTILITY_SERVICE']);


const b = $json.body ?? $json;
const problems = [];
if (!b.pseudonymId) problems.push('missing:pseudonymId');

const requested = b.scope === 'ALL' || !b.scope ? ALL_SCOPES : [].concat(b.scope);
const unknown = requested.filter((s) => !ALL_SCOPES.includes(s));
if (unknown.length) problems.push('unknown_scope:' + unknown.join('|'));

return [{ json: {
  ok: problems.length === 0,
  problems,
  runId: $execution.id,
  pseudonymId: b.pseudonymId ?? null,
  scopes: requested,
  revokeAll: b.scope === 'ALL' || !b.scope,
  // Erasure is a separate, explicit ask. Withdrawing consent does not silently
  // delete someone's results, because they may want them later.
  eraseData: b.eraseData === true,
  locale: b.locale === 'ar' ? 'ar' : 'en',
  reason: b.reason ?? null,
} }];

